127	    @Mapping(target = "idempotencyKey", ignore = true)
128	    Owner toOwner(OwnerDto ownerDto);
129	
130	    @Mapping(target = "id", ignore = true)
131	    @Mapping(target = "pets", ignore = true)
132	    @Mapping(target = "idempotencyKey", ignore = true)
