165	     */
166	    @Named("normalizeAddress")
167	    default String normalizeAddress(String address) {
168	        return AddressNormalizer.normalize(address);
169	    }
170	
171	    /**
172	     * Normalize a telephone number to canonical E.164 form (a leading {@code '+'}, country
173	     * code and national digits) so it is stored and returned in one comparable form and
174	     * duplicates can be detected by comparing these values. Format validity is enforced
175	     * separately by {@code TelephoneValidation} on the inbound DTO, so this only performs
176	     * the transform the stored value needs.
177	     */
178	    @Named("normalizeTelephone")
179	    default String normalizeTelephone(String telephone) {
180	        return TelephoneNormalizer.toE164(telephone);
181	    }
182	
183	    /**
184	     * Normalize an email address by trimming surrounding whitespace and lower-casing
185	     * it so it is stored and returned in a canonical form. Syntactic validity is
186	     * enforced separately by {@code @Email} on the inbound DTO, so this only performs
187	     * the transform the stored value needs.
188	     */
189	    @Named("normalizeEmail")
190	    default String normalizeEmail(String email) {
191	        return email == null ? null : email.trim().toLowerCase();
192	    }
193	
