120	
121	    /**
122	     * Derive the owner's read-only {@code salutation}: the honorific {@code title} and
123	     * {@code lastName} joined by a single space ({@code '<title> <lastName>'}) when a title has
124	     * been supplied, otherwise just the {@code lastName}. A {@code null} or blank title yields the
125	     * bare last name.
126	     */
127	    @Transient
128	    public String getSalutation() {
129	        if (this.title == null || this.title.isBlank()) {
130	            return getLastName();
131	        }
132	        return this.title + " " + getLastName();
133	    }
134	
135	    public String getAddress() {
136	        return this.address;
137	    }
138	
139	    public void setAddress(String address) {
140	        this.address = address;
141	    }
142	
143	    public String getAddressLine1() {
144	        return this.addressLine1;
145	    }
146	
147	    public void setAddressLine1(String addressLine1) {
148	        this.addressLine1 = addressLine1;
149	    }
150	
151	    public String getAddressLine2() {
152	        return this.addressLine2;
153	    }
154	
155	    public void setAddressLine2(String addressLine2) {
156	        this.addressLine2 = addressLine2;
157	    }
158	
159	    public String getCity() {
160	        return this.city;
161	    }
162	
163	    public void setCity(String city) {
164	        this.city = city;
165	    }
166	
167	    public String getPostcode() {
168	        return this.postcode;
169	    }
170	
171	    public void setPostcode(String postcode) {
172	        this.postcode = postcode;
173	    }
174	
175	    public String getTelephone() {
176	        return this.telephone;
177	    }
178	
179	    public void setTelephone(String telephone) {
180	        this.telephone = telephone;
181	    }
182	
183	    public String getEmail() {
184	        return this.email;
185	    }
186	
187	    public void setEmail(String email) {
188	        this.email = email;
189	    }
190	
191	    public LocalDate getRegistrationDate() {
192	        return this.registrationDate;
193	    }
194	
195	    public void setRegistrationDate(LocalDate registrationDate) {
196	        this.registrationDate = registrationDate;
197	    }
198	
199	    public LocalDate getBirthDate() {
200	        return this.birthDate;
201	    }
202	
203	    public void setBirthDate(LocalDate birthDate) {
204	        this.birthDate = birthDate;
205	    }
206	
207	    /**
208	     * Derive the owner's read-only {@code ageBand} from {@code birthDate}, computed against the
209	     * owner's {@code registrationDate} (falling back to the current date when no registration date
210	     * has been assigned yet): {@code MINOR} when under 18, {@code ADULT} from 18 to 64 inclusive,
211	     * {@code SENIOR} at 65 or older. Returns {@code null} when no {@code birthDate} has been supplied.
212	     */
213	    @Transient
214	    public String getAgeBand() {
215	        if (this.birthDate == null) {
216	            return null;
217	        }
218	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
219	        int age = Period.between(this.birthDate, reference).getYears();
220	        if (age < 18) {
221	            return "MINOR";
222	        }
223	        if (age < 65) {
224	            return "ADULT";
225	        }
226	        return "SENIOR";
227	    }
228	
229	    public String getCustomerCode() {
230	        return this.customerCode;
231	    }
232	
233	    public void setCustomerCode(String customerCode) {
234	        this.customerCode = customerCode;
235	    }
236	
237	    public String getMembershipNumber() {
238	        return this.membershipNumber;
239	    }
240	
241	    public void setMembershipNumber(String membershipNumber) {
242	        this.membershipNumber = membershipNumber;
243	    }
244	
245	    public String getHouseholdId() {
246	        return this.householdId;
247	    }
248	
249	    public void setHouseholdId(String householdId) {
250	        this.householdId = householdId;
251	    }
252	
253	    public Integer getNamesakeCount() {
254	        return this.namesakeCount;
255	    }
256	
257	    public void setNamesakeCount(Integer namesakeCount) {
258	        this.namesakeCount = namesakeCount;
259	    }
260	
261	    /**
262	     * Derive the owner's {@code membershipPoints}: a score starting at 0 that adds 2 when an email
263	     * is present, adds 1 when the owner's name was unique at creation time ({@code namesakeCount}
264	     * is 0), adds 2 when the owner belongs to a household of three or more members, and adds 3 when
265	     * the owner's tenure is at least one elapsed fiscal year (measured from the
266	     * {@code registrationDate} to today, where the fiscal year starts on 1 July).
267	     */
268	    @Transient
269	    public Integer getMembershipPoints() {
270	        int points = 0;
271	        if (this.email != null && !this.email.isBlank()) {
272	            points += 2;
273	        }
274	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
275	            points += 1;
276	        }
277	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
278	            points += 2;
279	        }
280	        if (hasTenureOverOneFiscalYear()) {
281	            points += 3;
282	        }
283	        return points;
284	    }
285	
286	    /**
287	     * Derive the owner's numeric {@code membershipLevel}, from 1 to 4, by mapping the owner's
288	     * {@code membershipPoints}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5
289	     * points, and level 4 for 6 or more points. The result is then capped at the owner's
290	     * {@code membershipLevelCap} when one has been assigned, so a new household member can never
291	     * exceed one above the highest level already present in their household (see
292	     * {@link #getMembershipLevelCap()}).
293	     */
294	    @Transient
295	    public Integer getMembershipLevel() {
296	        int points = getMembershipPoints();
297	        int level;
298	        if (points <= 1) {
299	            level = 1;
300	        }
301	        else if (points <= 3) {
302	            level = 2;
303	        }
304	        else if (points <= 5) {
305	            level = 3;
306	        }
307	        else {
308	            level = 4;
309	        }
310	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
311	            return this.membershipLevelCap;
312	        }
313	        return level;
314	    }
315	
316	    /**
317	     * The ceiling applied to this owner's derived {@code membershipLevel}: one above the highest
318	     * {@code membershipLevel} among the owner's household members (same last name and postcode) at
319	     * creation time. {@code null} when the owner had no existing household member, in which case no
320	     * cap applies.
321	     */
322	    public Integer getMembershipLevelCap() {
323	        return this.membershipLevelCap;
324	    }
325	
326	    public void setMembershipLevelCap(Integer membershipLevelCap) {
327	        this.membershipLevelCap = membershipLevelCap;
328	    }
329	
330	    /**
331	     * Whether the owner's tenure, measured as the number of elapsed fiscal years from
332	     * {@code registrationDate} to today (the fiscal year starting on 1 July), is at least one —
333	     * worth 3 membership points. A missing {@code registrationDate} (and therefore zero tenure)
334	     * never qualifies.
335	     */
336	    @Transient
337	    private boolean hasTenureOverOneFiscalYear() {
338	        if (this.registrationDate == null) {
339	            return false;
340	        }
341	        return fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) >= 1;
342	    }
343	
344	    /**
345	     * Derive the owner's read-only {@code fiscalYear}: {@code 'FY<YY>'} where YY is the last two
346	     * digits of the fiscal year of the owner's business-day-adjusted {@code registrationDate}. The
347	     * fiscal year starts on 1 July, so a registration on or after 1 July belongs to the fiscal year
348	     * ending the following 30 June. Returns {@code null} when no {@code registrationDate} has been
349	     * assigned yet, so the field is omitted from the response.
350	     */
351	    @Transient
352	    public String getFiscalYear() {
353	        if (this.registrationDate == null) {
354	            return null;
355	        }
356	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
357	    }
358	
359	    /**
360	     * The fiscal year a {@code date} falls in, identified by its ending calendar year. The fiscal
361	     * year starts on 1 July, so dates on or after 1 July belong to the following year's fiscal year
362	     * (e.g. 1 July 2026 is fiscal year 2027), while dates from 1 January to 30 June belong to the
363	     * current year's fiscal year.
364	     */
365	    public static int fiscalYearOf(LocalDate date) {
